# Training data: immutable, hashed shards generated by the R engine.
#
# Sources (kept apart in the manifest):
#   teacher_trajectory  positions along seeded random-walk games from the
#                       start, each labelled with the alpha-beta search's
#                       chosen action (one-hot target, small node budget)
#                       and, separately, its normalised heuristic score
#                       (auxiliary head). Walks stop at a ply cap: they are
#                       truncated, so they carry no outcome target.
#   fixture_game        tactical fixtures (mate in one, a forced loss, the
#                       platform escape, a queen capture, the promotion that
#                       avoids stalemate) played by the search agent to a
#                       true terminal state when one is reached within the
#                       cap; only then do their positions get WDL labels.
#   edited_position     seeded set-up positions with a lone piece on a
#                       platform, so platform actions (including transport
#                       promotion) occur; labelled like teacher positions.
#   self_play           written by g3_self_play() (MCTS visit targets).
#
# Splits are assigned per complete game (deterministic hash of seed and
# game id); fixture games are designated train or tactical holdout
# explicitly. Duplicate audit: full positions are compared by a key that
# includes the repetition record and halfmove counter (history matters for
# value targets); records in validation or holdout splits whose full key
# occurs in train are removed and counted, and board-only overlaps (shared
# starting positions) are reported separately, not used to merge games.
#
# Each split becomes one safetensors shard (features from the R encoder,
# policy targets aligned to the canonical candidate order, masks) plus a
# JSONL file with one record per position: game id, ply, source, the full
# canonical state, legal action ids, candidate digest, target source and
# target, outcome status. The manifest lists every file with its SHA-256.

.G3_DATASET_FORMAT <- "g3-dataset/1"
.G3_DATASET_GENERATOR <- "g3-dataset-generator/1"
.G3_OUTCOME_CODE <- c(win = 0L, draw = 1L, loss = 2L)

#' @noRd
.g3_ml_data_spec <- function(spec = list()) {
  d <- list(seed = 20261026L, games = 12L, max_walk_plies = 24L, positions = 240L,
            teacher = list(nodes = 400L, depth = 3L), fixtures = TRUE, fixture_nodes = 20000L,
            fixture_max_plies = 16L, platform_positions = 24L, split = c(train = 0.8, validation = 0.2),
            aux_scale = 400, max_positions = 512L)
  unknown <- setdiff(names(spec), names(d))
  if (length(unknown)) .g3_abort("g3_budget_exceeded", paste0("Unknown dataset setting: ", unknown[1L]))
  d[names(spec)] <- spec
  d
}

# Tactical fixtures (positions from the engine tests). `split` designates
# where each fixture game goes.
#' @noRd
.g3_ml_fixtures <- function() {
  P <- function(...) {
    x <- strsplit(c(...), " ", fixed = TRUE)
    data.frame(id = vapply(x, `[`, "", 1L), type = vapply(x, `[`, "", 2L), color = vapply(x, `[`, "", 3L),
               square_id = vapply(x, `[`, "", 4L), stringsAsFactors = FALSE)
  }
  net <- c("wK K white WK:0:0", "bQ Q black B:0:0", "bRd R black N:2:3", "bRf R black BK:1:1", "bK K black B:0:3")
  list(
    mate_in_one = list(state = g3_setup_position(P(net), side = "black"), split = "train",
                       note = "black mates with the queen on the e-file"),
    forced_loss = list(state = g3_setup_position(P(net), side = "white"), split = "tactical",
                       note = "every white action allows mate in one"),
    platform_escape = list(state = g3_setup_position(P("wK K white WK:0:0", "bN N black W:2:1", "bR1 R black W:0:0",
                                                       "bR2 R black BK:1:1", "bK K black B:0:3")),
                           split = "train", note = "the only legal action is a platform relocation"),
    queen_capture = list(state = g3_setup_position(P("wR R white W:0:0", "wK K white WK:0:0", "bQ Q black W:0:3",
                                                     "bK K black B:3:3")), split = "tactical",
                         note = "an undefended queen can be taken"),
    promotion_choice = list(state = g3_setup_position(P("wP P white B:1:2", "wPb P white B:0:2", "wK K white W:0:0",
                                                        "bK K black BQ:0:1", "bP P black BQ:1:0")),
                            split = "tactical", note = "promoting to a queen stalemates; a rook does not"),
    platform_promotion = list(state = g3_setup_position(P("wK K white W:0:0", "wP P white WQ:0:1", "bK K black N:3:3"),
                                                        docks = c(WQ = "B:R:lo", WK = "W:R:lo", BQ = "N:L:lo", BK = "B:L:hi")),
                              split = "train", note = "a platform carries a pawn to a promotion dock (transport promotion)")
  )
}

# Seeded edited positions with one piece alone on a platform.
#' @noRd
.g3_ml_platform_positions <- function(n, seed, tabs = .g3_tables()) {
  if (n <= 0L) return(list())
  out <- list()
  .g3_with_seed(seed, {
    tries <- 0L
    while (length(out) < n && tries < n * 60L) {
      tries <- tries + 1L
      side <- sample(c("white", "black"), 1L)
      plat <- sample(1:4, 1L)
      psq <- tabs$plat_squares[[plat]]
      lone_sq <- sample(psq, 1L)
      lone_type <- sample(c("P", "N", "B", "R", "Q", "K"), 1L, prob = c(3, 2, 2, 2, 1, 2))
      main <- setdiff(1:48, integer())
      used <- c(lone_sq, psq)
      ksq <- if (lone_type == "K") lone_sq else sample(setdiff(main, used), 1L)
      used <- c(used, ksq)
      osq <- sample(setdiff(main, used), 1L)
      used <- c(used, osq)
      extra <- sample(setdiff(main, used), sample(0:2, 1L))
      other <- if (side == "white") "black" else "white"
      ids <- c("L", if (lone_type != "K") "K1", "K2", if (length(extra)) paste0("X", seq_along(extra)))
      sqs <- c(lone_sq, if (lone_type != "K") ksq, osq, extra)
      types <- c(lone_type, if (lone_type != "K") "K", "K", sample(c("P", "N", "B", "R"), length(extra), replace = TRUE))
      cols <- c(side, if (lone_type != "K") side, other, sample(c("white", "black"), length(extra), replace = TRUE))
      pcs <- data.frame(id = ids, type = types, color = cols, square_id = tabs$sq_id[sqs], stringsAsFactors = FALSE)
      st <- tryCatch(g3_setup_position(pcs, side = side), error = function(e) NULL)
      if (is.null(st) || identical(st$outcome$status, "terminal")) next
      a <- g3_legal_actions(st)
      if (!any(a$type == "platform")) next
      out[[length(out) + 1L]] <- st
    }
  })
  out
}

# Alpha-beta teacher label: chosen action and heuristic score.
#' @noRd
.g3_ml_teacher <- function(core, tabs, teacher) {
  b <- .g3_budget(list(nodes = teacher$nodes, depth = teacher$depth))
  r <- .g3_root_search(core, tabs, b)
  list(action_id = r$ids[r$best], score = r$scores[r$best], status = r$status, depth = r$depth, nodes = r$nodes)
}

#' @noRd
.g3_ml_aux_target <- function(score, scale) {
  if (is.na(score)) return(NA_real_)
  if (abs(score) > .G3_MATE_BOUND) return(sign(score) * 1)
  tanh(score / scale)
}

# One training record (list) for a core position.
#' @noRd
.g3_ml_record <- function(core, tabs, game_id, ply, source, split, target_ids, target_probs, target_source,
                          aux = NA_real_, aux_source = NA_character_, edited = FALSE) {
  ctx <- .g3_ctx(core, tabs)
  legal <- .g3_legal(core, tabs, ctx)
  enc <- .g3_encode_core(core, tabs, ctx, legal)
  st <- .g3_state_from_core(core, .g3_outcome_core(core, tabs, ctx, legal), tabs)
  key <- core$rep[length(core$rep)]
  pt <- numeric(length(enc$action_ids))
  if (length(target_ids)) {
    j <- match(target_ids, enc$action_ids)
    if (anyNA(j)) .g3_abort("g3_invalid_state", "A policy target names an action that is not legal.")
    pt[j] <- target_probs
  }
  list(
    enc = enc,
    meta = list(
      game_id = game_id, ply = as.integer(core$ply), sequence = as.integer(ply), source = source, split = split,
      edited_position = edited, rules_hash = tabs$rules_hash, state = .g3_state_plain(st),
      state_hash = .g3_state_hash(st), position_key = key,
      dedup_key = .g3_sha256(paste(key, .g3_sha256(paste(core$rep, collapse = "|")), core$halfmove, sep = "#")),
      action_ids = as.list(enc$action_ids), candidate_digest = enc$candidate_digest,
      target_source = target_source, policy_available = length(target_ids) > 0L,
      policy_target = as.list(stats::setNames(target_probs, target_ids)),
      outcome = NA_character_, outcome_status = "none", aux_target = aux, aux_source = aux_source
    ),
    policy = pt,
    side = core$side
  )
}

# Set the outcome of every record of a game from its final state.
#' @noRd
.g3_ml_label_outcome <- function(recs, final_core, final_outcome, truncated) {
  for (i in seq_along(recs)) {
    if (truncated || !identical(final_outcome$status, "terminal")) {
      recs[[i]]$meta$outcome_status <- "truncated"
      recs[[i]]$meta$outcome <- NA_character_
    } else {
      res <- final_outcome$result
      side <- .G3_COLORS[recs[[i]]$side]
      recs[[i]]$meta$outcome <- if (identical(res, "draw")) "draw" else if (identical(res, side)) "win" else "loss"
      recs[[i]]$meta$outcome_status <- "terminal"
      recs[[i]]$meta$terminal_reason <- final_outcome$reason
    }
  }
  recs
}

#' @noRd
.g3_ml_split_of <- function(game_id, seed, fractions) {
  u <- strtoi(substr(.g3_sha256(paste(seed, game_id, sep = "|")), 1L, 7L), 16L) / 16^7
  cut <- cumsum(fractions) / sum(fractions)
  names(fractions)[which(u < cut)[1L]]
}

# Build a dataset into `dir`. Returns the manifest (also written as
# dataset.json). `progress(done, total)` is optional. `should_stop()` is
# polled before every teacher search (once per position, also inside a
# game); when it returns TRUE generation ends cleanly: nothing is written
# (a resumed run regenerates the same seeded data) and a
# `g3_dataset_stopped` record is returned instead of a manifest.
#' @noRd
.g3_ml_build_dataset <- function(spec = list(), dir, progress = NULL, should_stop = NULL) {
  s <- .g3_ml_data_spec(spec)
  tabs <- .g3_tables()
  dir.create(dir, recursive = TRUE, showWarnings = FALSE)
  t0 <- proc.time()[["elapsed"]]
  recs <- list()
  games <- list()
  budget_left <- function() as.integer(s$max_positions) - length(recs)
  stop_now <- function() is.function(should_stop) && isTRUE(should_stop())
  stopped <- function(n_records) {
    structure(list(stopped = TRUE, records_generated = as.integer(n_records), dir = dir,
                   elapsed_seconds = proc.time()[["elapsed"]] - t0), class = "g3_dataset_stopped")
  }
  # 1. Fixture games played to a terminal state where possible.
  if (isTRUE(s$fixtures)) {
    fx <- .g3_ml_fixtures()
    for (nm in names(fx)) {
      core <- .g3_core(fx[[nm]]$state, tabs)
      gid <- paste0("fixture-", nm)
      grec <- list()
      k <- 0L
      oc <- .g3_outcome_core(core, tabs)
      while (!identical(oc$status, "terminal") && k < s$fixture_max_plies && budget_left() > length(grec)) {
        if (stop_now()) return(stopped(length(recs) + length(grec)))
        t <- .g3_ml_teacher(core, tabs, list(nodes = s$fixture_nodes, depth = 6L))
        grec[[length(grec) + 1L]] <- .g3_ml_record(core, tabs, gid, k, "fixture_game", fx[[nm]]$split, t$action_id, 1,
                                                    "alpha_beta_choice", .g3_ml_aux_target(t$score, s$aux_scale),
                                                    "alpha_beta_score_tanh", edited = TRUE)
        legal <- .g3_legal(core, tabs)
        core <- .g3_make(core, legal[match(t$action_id, .g3_action_ids(core, legal, tabs)), ], tabs)
        oc <- .g3_outcome_core(core, tabs)
        k <- k + 1L
      }
      truncated <- !identical(oc$status, "terminal")
      grec <- .g3_ml_label_outcome(grec, core, oc, truncated)
      games[[gid]] <- list(game_id = gid, source = "fixture_game", split = fx[[nm]]$split, plies = k,
                           status = if (truncated) "truncated" else "terminal",
                           result = if (truncated) NA_character_ else oc$result,
                           reason = if (truncated) "max_plies" else oc$reason, note = fx[[nm]]$note)
      recs <- c(recs, grec)
    }
  }
  # 2. Platform-rich edited positions (one record each).
  for (i in seq_along(pl <- .g3_ml_platform_positions(min(s$platform_positions, budget_left()), s$seed + 1L, tabs))) {
    core <- .g3_core(pl[[i]], tabs)
    if (stop_now()) return(stopped(length(recs)))
    t <- .g3_ml_teacher(core, tabs, s$teacher)
    gid <- sprintf("edited-platform-%03d", i)
    sp <- .g3_ml_split_of(gid, s$seed, s$split)
    r <- .g3_ml_record(core, tabs, gid, 0L, "edited_position", sp, t$action_id, 1, "alpha_beta_choice",
                       .g3_ml_aux_target(t$score, s$aux_scale), "alpha_beta_score_tanh", edited = TRUE)
    r$meta$outcome_status <- "none"
    recs[[length(recs) + 1L]] <- r
    games[[gid]] <- list(game_id = gid, source = "edited_position", split = sp, plies = 0L, status = "edited",
                         result = NA_character_, reason = NA_character_, note = "seeded set-up position")
  }
  # 3. Teacher-labelled random walks from the start (truncated games).
  n_teacher <- min(as.integer(s$positions), budget_left())
  per_game <- max(1L, ceiling(n_teacher / max(1L, s$games)))
  done <- 0L
  for (g in seq_len(s$games)) {
    if (done >= n_teacher) break
    gid <- sprintf("walk-%03d", g)
    sp <- .g3_ml_split_of(gid, s$seed, s$split)
    core <- .g3_initial_core(tabs)
    grec <- list()
    plies <- .g3_with_seed(s$seed + g, sample.int(s$max_walk_plies + 1L, 1L) - 1L)
    k <- 0L
    oc <- .g3_outcome_core(core, tabs)
    while (!identical(oc$status, "terminal") && length(grec) < per_game && done + length(grec) < n_teacher) {
      if (stop_now()) return(stopped(length(recs) + length(grec)))
      t <- .g3_ml_teacher(core, tabs, s$teacher)
      grec[[length(grec) + 1L]] <- .g3_ml_record(core, tabs, gid, k, "teacher_trajectory", sp, t$action_id, 1,
                                                  "alpha_beta_choice", .g3_ml_aux_target(t$score, s$aux_scale),
                                                  "alpha_beta_score_tanh")
      if (k >= plies) break
      legal <- .g3_legal(core, tabs)
      # The walk itself: seeded uniform choices (diverse, legal positions).
      j <- .g3_with_seed(s$seed * 7L + g * 1000L + k, sample.int(nrow(legal), 1L))
      core <- .g3_make(core, legal[j, ], tabs)
      oc <- .g3_outcome_core(core, tabs)
      k <- k + 1L
    }
    truncated <- !identical(oc$status, "terminal")
    grec <- .g3_ml_label_outcome(grec, core, oc, truncated)
    games[[gid]] <- list(game_id = gid, source = "teacher_trajectory", split = sp, plies = k,
                         status = if (truncated) "truncated" else "terminal",
                         result = if (truncated) NA_character_ else oc$result,
                         reason = if (truncated) "walk_cap" else oc$reason, note = "seeded random walk")
    recs <- c(recs, grec)
    done <- done + length(grec)
    if (is.function(progress)) progress(length(recs), s$max_positions)
  }
  man <- .g3_ml_write_dataset(recs, games, dir, s, generator = "teacher_and_fixtures",
                              elapsed = proc.time()[["elapsed"]] - t0)
  man
}

# Deduplicate, shard and write. `recs` is a list from .g3_ml_record().
#' @noRd
.g3_ml_write_dataset <- function(recs, games, dir, spec, generator, elapsed = NA_real_, extra = list()) {
  dir.create(dir, recursive = TRUE, showWarnings = FALSE)
  tabs <- .g3_tables()
  sch <- .g3_feature_schema()
  splits <- vapply(recs, function(r) r$meta$split, "")
  dkey <- vapply(recs, function(r) r$meta$dedup_key, "")
  pkey <- vapply(recs, function(r) r$meta$position_key, "")
  # Remove from non-train splits the full positions present in train.
  in_train <- dkey %in% dkey[splits == "train"]
  drop <- splits != "train" & in_train
  removed <- table(factor(splits[drop], levels = setdiff(unique(splits), "train")))
  within <- sapply(unique(splits), function(sp) sum(duplicated(dkey[splits == sp])))
  board_overlap <- length(intersect(pkey[splits == "train"], pkey[splits != "train"]))
  start_key <- .g3_key_core(.g3_initial_core(tabs), tabs)
  shared_start <- sum(pkey == start_key)
  recs <- recs[!drop]
  splits <- splits[!drop]
  shards <- list()
  rec_files <- list()
  for (sp in sort(unique(splits))) {
    rs <- recs[splits == sp]
    n <- length(rs)
    stk <- .g3_enc_stack(lapply(rs, function(r) r$enc))
    a <- stk$cand_cat$shape[2L]
    pt <- numeric(n * a)
    for (i in seq_len(n)) {
      k <- length(rs[[i]]$policy)
      if (k) pt[(i - 1L) * a + seq_len(k)] <- rs[[i]]$policy
    }
    outc <- vapply(rs, function(r) if (identical(r$meta$outcome_status, "terminal")) .G3_OUTCOME_CODE[[r$meta$outcome]] else -1L, 0L)
    auxv <- vapply(rs, function(r) as.numeric(r$meta$aux_target %||% NA_real_), 0)
    tens <- c(stk, list(
      policy_target = list(dtype = "F32", shape = c(n, a), data = pt),
      policy_mask = list(dtype = "I32", shape = n, data = as.integer(vapply(rs, function(r) isTRUE(r$meta$policy_available), TRUE))),
      outcome = list(dtype = "I32", shape = n, data = outc),
      aux_target = list(dtype = "F32", shape = n, data = ifelse(is.na(auxv), 0, auxv)),
      aux_mask = list(dtype = "I32", shape = n, data = as.integer(!is.na(auxv)))
    ))
    f <- sprintf("shard-%s-000.safetensors", sp)
    sha <- .g3_write_safetensors(tens, file.path(dir, f), metadata = list(format = .G3_DATASET_FORMAT, split = sp))
    shards[[length(shards) + 1L]] <- list(split = sp, file = f, sha256 = sha, n = n, max_candidates = a,
                                          n_policy = sum(tens$policy_mask$data), n_wdl = sum(outc >= 0L),
                                          n_aux = sum(tens$aux_mask$data))
    rf <- sprintf("records-%s.jsonl", sp)
    lines <- vapply(rs, function(r) as.character(jsonlite::toJSON(r$meta, auto_unbox = TRUE, digits = NA, null = "null", na = "null")), "")
    .g3_atomic_write(paste0(paste(lines, collapse = "\n"), "\n"), file.path(dir, rf))
    rec_files[[length(rec_files) + 1L]] <- list(split = sp, file = rf, sha256 = .g3_file_sha256(file.path(dir, rf)), n = n)
  }
  gl <- unname(games)
  split_map <- stats::setNames(lapply(gl, function(g) g$split), vapply(gl, function(g) g$game_id, ""))
  split_map <- split_map[order(names(split_map), method = "radix")]
  src <- vapply(recs, function(r) r$meta$source, "")
  ost <- vapply(recs, function(r) r$meta$outcome_status, "")
  man <- c(list(
    format = .G3_DATASET_FORMAT,
    dataset_id = paste0("ds-", substr(.g3_sha256(paste(vapply(shards, function(x) x$sha256, ""), collapse = "")), 1L, 16L)),
    created = .g3_now(),
    generator = list(name = generator, version = .G3_DATASET_GENERATOR,
                     package_version = as.character(utils::packageVersion("gambitR3D"))),
    rules = list(version = tabs$rules_version, hash = tabs$rules_hash),
    engine = list(search = .G3_SEARCH_VERSION, evaluator = .G3_EVAL_VERSION, backend = .g3_engine(),
                  action_schema = .G3_ACTION_SCHEMA),
    feature_schema = sch$name, feature_schema_hash = sch$hash, action_schema_hash = .g3_action_schema_hash(),
    spec = spec,
    provenance = list(source = "generated locally by the gambitR3D rules engine", external_data = "none",
                      user_games = "none", edited_positions = "fixtures and seeded set-up positions are labelled edited_position = true"),
    games = gl,
    split_assignment = split_map,
    split_hash = .g3_hash_object(split_map),
    counts = list(
      records = length(recs),
      by_split = as.list(table(splits)),
      by_source = as.list(table(src)),
      by_outcome_status = as.list(table(ost)),
      games = length(gl),
      terminal_games = sum(vapply(gl, function(g) identical(g$status, "terminal"), TRUE)),
      truncated_games = sum(vapply(gl, function(g) identical(g$status, "truncated"), TRUE))
    ),
    dedup = list(
      policy = "full key = position key + repetition-record hash + halfmove; validation/tactical records whose full key occurs in train are removed",
      removed_from = as.list(removed), within_split_duplicates = as.list(within),
      board_only_overlap_keys = board_overlap, records_at_start_position = shared_start
    ),
    truncation = "truncated games are never draws: their outcome target is -1 (masked)",
    shards = shards,
    records = rec_files,
    elapsed_seconds = elapsed
  ), extra)
  txt <- jsonlite::toJSON(man, auto_unbox = TRUE, pretty = TRUE, digits = NA, null = "null", na = "null")
  .g3_atomic_write(txt, file.path(dir, "dataset.json"))
  man$manifest_path <- normalizePath(file.path(dir, "dataset.json"))
  man$manifest_sha256 <- .g3_file_sha256(man$manifest_path)
  structure(man, class = "g3_dataset")
}

# Read a dataset manifest (path to dataset.json or its directory).
#' @noRd
.g3_ml_read_dataset <- function(path) {
  p <- if (dir.exists(path)) file.path(path, "dataset.json") else path
  if (!file.exists(p)) .g3_abort("g3_io_error", paste0("No dataset manifest at ", p))
  man <- jsonlite::fromJSON(p, simplifyVector = FALSE)
  if (!identical(man$format, .G3_DATASET_FORMAT)) .g3_abort("g3_io_error", "Unknown dataset format.")
  if (!identical(man$rules$hash, .g3_tables()$rules_hash)) {
    .g3_abort("g3_unsupported_rules", "The dataset was generated under a different rules hash.")
  }
  if (!identical(man$feature_schema_hash, .g3_feature_schema()$hash)) {
    .g3_abort("g3_incompatible_model", "The dataset was encoded with a different feature schema.")
  }
  man$manifest_path <- normalizePath(p)
  man$manifest_sha256 <- .g3_file_sha256(p)
  structure(man, class = "g3_dataset")
}

# Re-check a written dataset: file hashes, and for every record that the
# stored state reproduces the same legal actions, candidate digest and
# encoded tensors, and that the policy target is aligned.
#' @noRd
.g3_ml_verify_dataset <- function(path) {
  man <- .g3_ml_read_dataset(path)
  dir <- dirname(man$manifest_path)
  problems <- character()
  checked <- 0L
  for (sh in man$shards) {
    f <- file.path(dir, sh$file)
    if (!identical(.g3_file_sha256(f), sh$sha256)) {
      problems <- c(problems, paste0(sh$file, ": hash"))
      next
    }
    t <- .g3_read_safetensors(f)
    rf <- Filter(function(r) identical(r$split, sh$split), man$records)[[1L]]
    if (!identical(.g3_file_sha256(file.path(dir, rf$file)), rf$sha256)) problems <- c(problems, paste0(rf$file, ": hash"))
    lines <- readLines(file.path(dir, rf$file), warn = FALSE)
    a <- sh$max_candidates
    kc <- t$cand_cat$shape[3L]
    for (i in seq_along(lines)) {
      r <- jsonlite::fromJSON(lines[i], simplifyVector = FALSE)
      st <- .g3_state_from_list(r$state)
      enc <- .g3_encode_state(st)
      ids <- unlist(r$action_ids)
      if (!identical(enc$action_ids, ids) || !identical(enc$candidate_digest, r$candidate_digest)) {
        problems <- c(problems, paste0(sh$split, " record ", i, ": legal actions differ"))
        next
      }
      n <- length(ids)
      if (t$n_cand$data[i] != n) problems <- c(problems, paste0(sh$split, " record ", i, ": candidate count"))
      cc <- t$cand_cat$data[(i - 1L) * a * kc + seq_len(n * kc)]
      if (!identical(as.integer(cc), as.vector(t(enc$cand_cat)))) problems <- c(problems, paste0(sh$split, " record ", i, ": candidate features"))
      pt <- t$policy_target$data[(i - 1L) * a + seq_len(n)]
      tgt <- r$policy_target
      if (length(tgt)) {
        j <- match(names(tgt), ids)
        if (anyNA(j) || any(abs(pt[j] - unlist(tgt)) > 1e-6) || abs(sum(pt) - sum(unlist(tgt))) > 1e-6) {
          problems <- c(problems, paste0(sh$split, " record ", i, ": policy target misaligned"))
        }
      }
      oc <- t$outcome$data[i]
      if (identical(r$outcome_status, "terminal") != (oc >= 0L)) problems <- c(problems, paste0(sh$split, " record ", i, ": outcome mask"))
      checked <- checked + 1L
    }
  }
  list(valid = !length(problems), checked = checked, problems = problems)
}

#' @export
print.g3_dataset <- function(x, ...) {
  cat("<g3_dataset> ", x$dataset_id, ": ", x$counts$records, " records in ", length(x$shards), " shard(s); ",
      x$counts$terminal_games, " terminal and ", x$counts$truncated_games, " truncated games\n", sep = "")
  invisible(x)
}
